# owner: platform
"""Snap span edges to a fixed step for payroll."""

from hourglass.parsing import format_clock
from hourglass.models import Span


def check_step(step: int) -> None:
    """Steps must be whole minutes that divide an hour."""
    if isinstance(step, bool) or not isinstance(step, int):
        raise ValueError(f"step must be an int: {step!r}")
    if step <= 0:
        raise ValueError(f"step must be positive: {step}")
    if 60 % step:
        raise ValueError(f"step must divide 60: {step}")


def snap(value: int, step: int) -> int:
    """Nearest multiple of step, with halves going up."""
    return (2 * value + step) // (2 * step) * step


def round_span(span: Span, step: int) -> Span:
    """Round both edges. Raises if the span collapses."""
    check_step(step)
    begin = snap(span.start, step)
    finish = snap(span.end, step)
    if begin >= finish:
        raise ValueError(
            f"span vanishes at step {step}: {span}"
        )
    return Span(begin, finish)


def label_span(span: Span) -> str:
    """Label such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    clock = f"{format_clock(span.start)}-"
    clock += format_clock(span.end)
    return f"{clock} ({hours}h {extra}m)"


def round_labels(spans: list, step: int) -> list:
    """Round each span to the step and label it."""
    check_step(step)
    rounded = [round_span(item, step) for item in spans]
    return [label_span(item) for item in rounded]

