# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:00-17:15")]
        result = round_labels(spans, 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_edges_snap_to_nearest(self):
        spans = [parse_span("08:53-17:07")]
        result = round_labels(spans, 15)
        self.assertEqual(result, ["09:00-17:00 (8h 0m)"])

    def test_halves_round_up(self):
        result = round_span(Span(495, 1005), 30)
        self.assertEqual(result, Span(510, 1020))

    def test_each_span_gets_a_label(self):
        spans = [Span(0, 60), Span(600, 1440)]
        self.assertEqual(
            round_labels(spans, 30),
            ["00:00-01:00 (1h 0m)", "10:00-24:00 (14h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -5, 7, 45, 90, 120, 2.5, True):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels(spans, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 64)], 15)


if __name__ == "__main__":
    unittest.main()
